  ..addAll(['step-timings', 'release', 'js-ext-integration']);

List<String> _needsOf(YamlMap job) {
  final needs = job['needs'];
  if (needs is String) return [needs];
  if (needs is YamlList) return needs.map((n) => n.toString()).toList();
