          _needsOf(job),
          isNot(contains('release-pending')),
          reason: 'gh-1551 AC3: `$id` is never schedule-reachable — it '
              'must stay untouched',
        );
        expect(
          job['if']?.toString() ?? '',
          isNot(contains('release-pending')),
          reason: 'gh-1551 AC3: `$id` must stay untouched',
        );
      }
    });

