  final proc = await Process.run('python3', args);
  final out = '${proc.stdout}${proc.stderr}';
  expect(
    out,
    isNot(contains('Traceback')),
    reason: 'the guard must fail loud, never traceback: $out',
  );
  return proc.exitCode;

