/// guard (e.g. `if: needs.release-pending.outputs.pending == 'true'`)
/// would pass the plain presence pin while silently killing path
/// classification — the exact blind spot this never-again pin family
/// exists to close.
const pathBlindLegs = {
  'changes',
  'quality-gate',
  'step-timings',
  'release',
  'static',
  'test-core',
  'pty-visual',
  'coverage-gate',
  'guards',
  'dep-audit',
  'supply-chain',
  'installer-verify',
  'install-pin-gate',
  'fa-aot-build',
  'pty-integration-linux',
  'pty-coverage-gate',
  'js-ext-integration',
};

