const pathBlindLegs = {
  'changes',
  'quality-gate',
  'step-timings',
  'release',
  'static',
  'test-core',
  'pty-visual',
  'coverage-gate',
  'guards',
  'dep-audit',
  'supply-chain',
  'installer-verify',
  'install-pin-gate',
  'fa-aot-build',
  'pty-integration-linux',
  'pty-coverage-gate',
  'js-ext-integration',
};

void main() {
  final jobs = loadYaml(read('.github/workflows/ci.yml'))['jobs'] as YamlMap;

