      final job = jobs['release-pending'] as YamlMap?;
      expect(job, isNotNull, reason: 'gh-1551: the pre-check job must exist');
      expect(
        (job!['outputs'] as YamlMap)['pending'].toString(),
        r'${{ steps.check.outputs.pending }}',
