library;

import 'dart:convert';
import 'dart:io';

import 'package:test/test.dart';

const _script = 'scripts/sm_merge_guard.py';

const _sha = 'aaaabbbbccccdddd';
const _tree = 'tree1111';
const _subject = 'gh-999 some story (#1000)';

Future<int> runGuard(
  List<Map<String, Object?>> runs, {
  String subject = [REDACTED:Certificate DN],
  String sha = _sha,
  String tree = _tree,
  bool alarmIssue = false,
  // A repo that cannot exist: the alarm path must reach gh (and fail
  // there, cleanly) without any chance of filing a real issue.
  String repo = 'sm-guard-test/nonexistent-repo',
}) async {
  final dir = Directory.systemTemp.createTempSync('sm-merge-guard-');
  addTearDown(() => dir.deleteSync(recursive: true));
