      // collected on real runs.
      final gateIf = (jobs['quality-gate'] as YamlMap)['if'].toString();
      expect(gateIf, startsWith('always()'),
          reason: 'gh-1551 AC2: the aggregate keeps collecting leg results '
              'on every real run');
    });
  });

