      reason: 'the trigger comment quoted by gh-1625 must describe the '
          'new short-circuit, not the tolerated double-gate');
  expect(
    comment,
    isNot(contains('tolerates')),
    reason: 'the retired only-the-upload-is-idempotent note must stay '
        'retired',
  );
});

