{"content":"#!/usr/bin/env python3
"""gh-1625 graph simulator: evaluate ci.yml's ACTUAL needs/if expressions
under GitHub Actions semantics for the three release scenarios.

Models:
  - implicit success(): a job whose `if` contains NO status function
    (always/failure/cancelled) is force-skipped unless EVERY need ended
    'success';
  - !cancelled()/always() in `if`: needs results are readable but do not
    force-skip;
  - needs.X.outputs.Y / needs.X.result / github.event_name / github.ref /
    needs.changes.outputs.* substituted from the scenario.
"""
import re
import sys

import yaml

CI = ".github/workflows/ci.yml"
doc = yaml.safe_load(open(CI))
jobs = doc["jobs"]


def needs_of(job):
    n = job.get("needs", [])
    return [n] if isinstance(n, str) else list(n)


def has_status_func(ifexpr):
    return bool(
        re.search(r"always\(\)|failure\(\)|cancelled\(\)", ifexpr or "")
    )


def sanitize(expr, ctx):
    # needs.X.result -> R<X>; needs.X.outputs.Y -> O<X>_Y;
    # github.* -> G_*
    def sub(m):
        path = m.group(1).split(".")
        if path[0] == "needs":
            if path[2] == "result":
                return f"R_{path[1]}"
            if path[2] == "outputs":
                return f"O_{path[1]}_{path[3]}"
        if path[0] == "github":
            return f"G_{path[1]}"
        if path[0] == "inputs":
            return f"I_{path[1]}"
        return m.group(0)

    expr = re.sub(r"(needs|github|inputs)(\.[A-Za-z0-9-]+)+", sub, expr)
    expr = expr.replace("&&", " and ").replace("||", " or ")
    expr = expr.replace("!", " not ").replace(" notcancelled()", "True")
    expr = expr.replace("=='true'", "== 'true'").replace("!='true'", "!= 'true'")
    # remaining literals
    expr = expr.replace("startsWith(G_ref, 'refs/tags/v')", "'refs/tags/v' in G_ref")
    for k, v in ctx.items():
        expr = re.sub(rf"\b{k}\b", repr(v), expr)
    expr = re.sub(r"\bG_[A-Za-z_]+\b", "''", expr)
    expr = re.sub(r"\bO_[A-Za-z0-9_-]+\b", "''", expr)
    return expr


def run(event, ref, dedupe, pending, changes_out, extra_ctx=None):
    state = {}  # job -> 'success' | 'skipped' | 'failure'
    outputs = {
        "release-pending": {"pending": pending},
        "release-dedupe": {"dedupe": dedupe},
        "changes": {k: "true" if v else "" for k, v in changes_out.items()},
    }
    ctx = {
        "G_event_name": event,
        "G_ref": ref,
        "G_ref_name": ref.split("/")[-1],
        "I_releaseDryRun": "false",
        "I_releaseDispatch": "false",
    }
    # topological-ish loop
    for _ in range(len(jobs)):
        progressed = False
        for name, job in jobs.items():
            if name in state:
                continue
            needs = needs_of(job)
            if any(n not in state for n in needs):
                continue
            ifexpr = str(job.get("if", "success()")) if job.get("if") else "success()"
            if not has_status_func(ifexpr):
                if any(state[n] != "success" for n in needs):
                    state[name] = "skipped"
                    progressed = True
                    continue
            local = dict(ctx)
            for n in needs:
                local[f"R_{n}"] = state[n]
                for k, v in outputs.get(n, {}).items():
                    local[f"O_{n}_{k}"] = v
            py = sanitize(ifexpr, local)
            try:
                cond = eval(py, {"__builtins__": {}}, {})  # noqa: S307
            except Exception as e:  # noqa: BLE001
                sys.exit(f"{name}: cannot eval `{py}`: {e}")
            state[name] = "success" if cond else "skipped"
            progressed = True
        if len(state) == len(jobs):
            break
        if not progressed:
            sys.exit("graph stalled")
    return state


QUALITY = [
    "changes", "static", "test-core", "coverage-gate", "guards",
    "flutter-analyze", "flutter-tests", "app-crap-gate", "test-faui",
    "faui-coverage", "cli-visual-settings", "cube-kernel-live",
    "build-web", "build-android", "build-ios", "build-macos",
    "integration-mock", "hostile-env", "fa-aot-build",
    "pty-integration-linux", "pty-coverage-gate", "pty-visual",
    "supply-chain", "dep-audit", "installer-portability",
    "installer-verify", "install-pin-gate", "flutter-app-exzone",
    "flutter-app-lock-smoke", "perf-gate", "usage-fold", "js-ext-integration",
    "step-timings",
]

full_changes = {
    k: True
    for k in ["core", "app", "docs", "shared", "exzone", "locksmoke",
              "intmock", "installer", "perf", "usagefold"]
}

scenarios = {
    "AC1 hot path — tag push twin (full gate must run)": run(
        "push", "refs/tags/v9.9.9", "false", "true", full_changes),
    "AC1 hot path — release twin, push run exists (dedupe)": run(
        "release", "refs/tags/v9.9.9", "true", "true", full_changes),
    "AC2 — release on an old tag (no fresh push run)": run(
        "release", "refs/tags/v9.9.9", "false", "true", full_changes),
    "AC3 — SM validation dispatch (unchanged full gate)": run(
        "workflow_dispatch", "refs/heads/pr-1", "false", "true",
        full_changes),
    "AC3 — schedule tick with commits (unchanged full gate)": run(
        "schedule", "refs/heads/main", "false", "true", full_changes),
}

fails = []
for label, state in scenarios.items():
    print(f"\n== {label}")
    interesting = ["release-dedupe"] + QUALITY + [
        "quality-gate", "binaries", "web-spa", "integration", "publish",
        "release-provenance", "installer-smoke", "release", "ci-red-report",
    ]
    for j in interesting:
        mark = {"success": "RUN", "skipped": "skip", "failure": "FAIL"}[state[j]]
        print(f"   {mark}  {j}")
    if "push twin" in label:
        if state["quality-gate"] != "success" or state["binaries"] != "success":
            fails.append(label)
        if any(state[q] == "skipped" for q in QUALITY if q not in
               ("perf-gate", "flutter-app-exzone")):
            fails.append(label + " (a quality leg skipped on the push twin)")
    if "release twin, push run exists" in label:
        if any(state[q] != "skipped" for q in QUALITY):
            fails.append(label + " (a quality leg RAN on the deduped twin)")
        if state["binaries"] != "success":
            fails.append(label + " (binaries-attach did not run)")
        if state["web-spa"] != "skipped":
            fails.append(label + " (web-spa ran on the deduped twin)")
        if state["publish"] != "skipped" or state["integration"] != "skipped":
            fails.append(label + " (publish/integration ran off-event)")
    if "old tag" in label:
        if any(state[q] == "skipped" for q in QUALITY if q not in
               ("perf-gate", "flutter-app-exzone")):
            fails.append(label + " (the safety net did not run the full gate)")
        if state["binaries"] != "success" or state["web-spa"] != "success":
            fails.append(label + " (attach legs did not run)")
    if "dispatch" in label or "schedule tick" in label:
        if any(state[q] == "skipped" for q in QUALITY if q not in
               ("perf-gate", "flutter-app-exzone")):
            fails.append(label + " (AC3 regression: a leg no longer runs)")
        if state["binaries-pr"] if "binaries-pr" in state else False:
            pass

print()
if fails:
    print("SIMULATION FAILURES:")
    for f in fails:
        print("  -", f)
    sys.exit(1)
print("graph simulation green: AC1/AC2/AC3 semantics hold")
